import{_ as t,o,c as d,a0 as a}from"./chunks/framework.CfecN1Ke.js";const g=JSON.parse('{"title":"cypera.toml — the per-repo contract","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cypera-toml.md","filePath":"reference/cypera-toml.md"}'),c={name:"reference/cypera-toml.md"};function s(i,e,r,n,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="cypera-toml-—-the-per-repo-contract" tabindex="-1"><code>cypera.toml</code> — the per-repo contract <a class="header-anchor" href="#cypera-toml-—-the-per-repo-contract" aria-label="Permalink to &quot;`cypera.toml` — the per-repo contract&quot;">​</a></h1><p>Every generator discovers <code>cypera.toml</code> by walking upward from <code>--repo</code> (or the cwd). The file absorbs what the per-repo <code>docs/gen-*.py</code> wrappers used to hard-code: layer maps, markers, curated struct lists, titles, preambles, and output paths. With it present, <code>cypera gen …</code> needs no flags; <code>cypera check</code> uses it to verify generated files are fresh.</p><p>All keys are optional; an absent file means &quot;legacy mode&quot; (explicit flags only). Paths are repo-relative unless absolute. The serde model lives in <code>crates/cypera-core/src/repo_config.rs</code>.</p><h2 id="crate-map-—-cypera-gen-crate-map" tabindex="-1"><code>[crate_map]</code> — <code>cypera gen crate-map</code> <a class="header-anchor" href="#crate-map-—-cypera-gen-crate-map" aria-label="Permalink to &quot;`[crate_map]` — `cypera gen crate-map`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>type</th><th>meaning</th></tr></thead><tbody><tr><td><code>out</code></td><td>string</td><td>Full-page emit target, e.g. <code>docs/reference/crate-map.md</code>. Used when no <code>--out</code> flag and no splices/crate-api apply; also the freshness target for <code>check</code>.</td></tr><tr><td><code>order</code></td><td>string list</td><td>Layer sort order, replacing the default (<code>domain</code>, <code>port</code>, <code>adapter</code>, <code>ops</code>, <code>service</code>, <code>engine</code>, <code>driver</code>, <code>testkit</code>, <code>tooling</code>, <code>binary</code>, <code>impl</code>). Unknown layers sort last, alphabetically.</td></tr><tr><td><code>default_layer</code></td><td>string</td><td>Fallback layer for unclassified crates — the kuda/mimus <code>&quot;impl&quot;</code> convention. Default <code>&quot;adapter&quot;</code>.</td></tr><tr><td><code>[crate_map.layers]</code></td><td>table</td><td>Per-crate layer overrides: <code>&quot;my-crate-xtask&quot; = &quot;tooling&quot;</code>.</td></tr><tr><td><code>[[crate_map.splices]]</code></td><td>array</td><td>In-place table splices into existing pages. Each entry: <code>target</code> (required, repo-relative file), and exactly one of <code>marker</code> (replace the pipe-table run after the first line containing this string) or <code>first_table = true</code> (replace the first crate table — the no-marker convention).</td></tr><tr><td><code>[crate_map.crate_api]</code></td><td>table</td><td>Rustdoc link-list page: <code>site</code> (the docs-site name used in <code>/{site}/api/…</code> URLs) and <code>out</code> (e.g. <code>docs/reference/crate-api.md</code>).</td></tr></tbody></table><p>Splice example:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crate_map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">splices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/explanation/architecture.md&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">marker = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;!-- crate-map --&gt;&quot;</span></span></code></pre></div><h2 id="api-—-cypera-gen-api" tabindex="-1"><code>[api]</code> — <code>cypera gen api</code> <a class="header-anchor" href="#api-—-cypera-gen-api" aria-label="Permalink to &quot;`[api]` — `cypera gen api`&quot;">​</a></h2><p>The rustdoc API site — successor to the per-repo <code>docs/gen-api.py</code></p><ul><li><code>docs/gen-api-index.py</code> pair (and the inline <code>docs:api</code> shell bupha/kuda/mimus carried). <code>gen api</code> runs <code>cargo doc --workspace --no-deps</code> in the repo, resolves the real target dir via <code>cargo metadata</code>, empties the api dir, copies <code>&lt;target&gt;/doc</code> into it, and writes a styled <code>index.html</code> listing the crate dirs. Output is a gitignored build artifact — <code>check</code> freshness does not apply. Every key is optional; absent <code>[api]</code> means the python defaults.</li></ul><table tabindex="0"><thead><tr><th>key</th><th>type</th><th>meaning</th></tr></thead><tbody><tr><td><code>out</code></td><td>string</td><td>Rustdoc site dir, repo-relative. Default <code>docs/public/api</code>. A <code>--out</code> flag overrides it (a path, resolved against the cwd — run from the docs worktree to land in a detached docs checkout).</td></tr><tr><td><code>prefix</code></td><td>string</td><td>Crate-dir name prefix the index lists and the title is built from — the python <code>startswith(&quot;&lt;repo&gt;&quot;)</code> filter. Default: the repo directory name.</td></tr><tr><td><code>title</code></td><td>string</td><td>Index <code>&lt;title&gt;</code>/<code>&lt;h1&gt;</code> text. Default <code>&quot;{prefix} — Crate API&quot;</code>.</td></tr><tr><td><code>target_dir</code></td><td>string</td><td>Repo-relative cargo target dir exported as <code>CARGO_TARGET_DIR</code> for the doc build <strong>when the env var is unset</strong> — the myco <code>target/docs-api</code> isolation convention (a shared target dir served stale rmeta).</td></tr></tbody></table><p>Repo-root resolution keeps the python <code>&lt;NAME&gt;_ROOT</code> env convention: <code>&lt;NAME&gt;</code> is the <code>cypera.toml</code> dir&#39;s basename uppercased (<code>tamias</code> → <code>TAMIAS_ROOT</code>), and when set it overrides <code>--repo</code> — how detached-sha doc pipelines point cargo at the real checkout while <code>--out public/api</code> (cwd-relative, from the docs worktree) picks the output.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out        = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/public/api&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target/docs-api&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # myco&#39;s isolated doc target</span></span></code></pre></div><h2 id="cli-—-cypera-gen-cli" tabindex="-1"><code>[cli]</code> — <code>cypera gen cli</code> <a class="header-anchor" href="#cli-—-cypera-gen-cli" aria-label="Permalink to &quot;`[cli]` — `cypera gen cli`&quot;">​</a></h2><p>A recursive <code>&lt;bin&gt; --help</code> walk that reproduces the per-repo <code>gen-cli-docs.py</code> scripts byte-for-byte.</p><table tabindex="0"><thead><tr><th>key</th><th>type</th><th>meaning</th></tr></thead><tbody><tr><td><code>package</code></td><td>string</td><td>Cargo package to <code>cargo build -q -p</code> once, then invoke <code>target/debug/&lt;bin&gt;</code>. When absent, <code>bin</code> is executed directly (PATH or absolute path).</td></tr><tr><td><code>bin</code></td><td>string</td><td>Binary name under <code>target/debug/</code> (cargo mode) or the executable itself (direct mode). Required.</td></tr><tr><td><code>prefix</code></td><td>string list</td><td>Argv prefix before the walked subcommand path — the <code>[&quot;run&quot;]</code> engine-passthrough shim, or empty.</td></tr><tr><td><code>title</code></td><td>string</td><td>Page title override. Default: <code>Command-Line Help for</code> plus the program name derived from the root usage line.</td></tr><tr><td><code>out</code></td><td>string</td><td>Emit target — freshness check only; generation writes to stdout or <code>--out</code>.</td></tr></tbody></table><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cli</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">package = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lasius-driver&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tamias-driver-lasius&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prefix = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/reference/cli.md&quot;</span></span></code></pre></div><p>The walk skips the synthetic <code>help</code> command, follows <code>Commands</code> entries depth-first, and parses <code>Usage:</code>/about/<code>Arguments</code>/ <code>Commands</code>/<code>Options</code> sections exactly like the python scripts.</p><h2 id="config-—-cypera-gen-config" tabindex="-1"><code>[config]</code> — <code>cypera gen config</code> <a class="header-anchor" href="#config-—-cypera-gen-config" aria-label="Permalink to &quot;`[config]` — `cypera gen config`&quot;">​</a></h2><p>Curated config-reference pages — the successor to <code>gen-config-docs.py</code>&#39;s per-repo struct lists, type vocabularies, preambles, and prose sections.</p><table tabindex="0"><thead><tr><th>key</th><th>type</th><th>meaning</th></tr></thead><tbody><tr><td><code>out</code></td><td>string</td><td>Emit target for <code>check</code> freshness.</td></tr><tr><td><code>title</code></td><td>string</td><td><code># </code> page title.</td></tr><tr><td><code>files</code></td><td>string list</td><td>Rust sources to scan for <code>pub struct</code>s.</td></tr><tr><td><code>[[config.structs]]</code></td><td>array</td><td>Named struct lookups: <code>file</code> + <code>name</code> (+ optional <code>title</code>). A name matching no <code>pub struct</code> renders a header-only section — the python <code>fields() → []</code> behavior.</td></tr><tr><td><code>[config.types]</code></td><td>table</td><td>Rust type → display name (<code>&quot;Vec&lt;String&gt;&quot; = &quot;list&quot;</code>).</td></tr><tr><td><code>[config.field_types]</code></td><td>table</td><td><code>Struct.field</code> → display name, winning over <code>types</code>.</td></tr><tr><td><code>[[config.sections]]</code></td><td>array</td><td>Ordered page sections. Each has <code>title</code> + <code>level</code> (heading depth, default 2) and exactly one body: <code>struct</code> (a name from <code>structs</code>), <code>text</code> (inline markdown), or <code>text_file</code> (repo-relative markdown file). <code>struct</code> may combine with <code>text</code>/<code>text_file</code> for table-plus-prose sections.</td></tr><tr><td><code>[config.style]</code></td><td>table</td><td>Page-chrome overrides: <code>preamble</code> (prose between title and marker), <code>marker</code> (verbatim marker block), <code>table_head</code>/<code>table_sep</code> (custom field-table header/separator, e.g. tarsi&#39;s <code>key/meaning</code>). <code>preamble_file</code> reads the preamble from a repo-relative file.</td></tr></tbody></table><p>Field rules (python parity): only <code>///</code>-documented <code>pub</code> fields appear; <code>Option&lt;T&gt;</code> and a literal <code>serde(default</code> attribute mark a field optional and unwrap the inner type; notes escape <code>|</code>, <code>&lt;</code>, <code>&gt;</code>.</p><h2 id="check-—-cypera-check-profile-exemptions" tabindex="-1"><code>[check]</code> — <code>cypera check</code> profile + exemptions <a class="header-anchor" href="#check-—-cypera-check-profile-exemptions" aria-label="Permalink to &quot;`[check]` — `cypera check` profile + exemptions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>type</th><th>meaning</th></tr></thead><tbody><tr><td><code>profile</code></td><td>string</td><td>Docs-content profile — <code>engine</code>, <code>library</code>, or <code>content</code>. Drives the content rules (<code>content-pages</code>, <code>tutorial-count</code>, <code>tutorial-name</code>, <code>index-router</code>, <code>no-orphan-getting-started</code>). <code>engine</code> requires the full Diátaxis tree (all four quadrant dirs, ≥1 tutorial, ≥3 how-tos, and <code>explanation/{architecture,concepts,boundaries,decisions}.md</code>); <code>library</code> requires only <code>index.md</code> + <code>explanation/{architecture,concepts}.md</code>; <code>content</code> exempts narrative/site/ledger repos from the quadrant bar. Absent or unknown values warn on stderr and fall back to <code>engine</code>. All five rules SKIP when the <code>docs/</code> worktree isn&#39;t checked out, and when no <code>cypera.toml</code> exists at all.</td></tr><tr><td><code>skip</code></td><td>string list</td><td><code>cypera check</code> rule names reported <code>SKIP</code> (exempt) instead of their computed status — for repos where a rule doesn&#39;t apply by design (content-only ledger mounts, theme packages, the website repo). Rules: <code>readme</code>, <code>agents-md</code>, <code>no-changelog</code>, <code>no-version-in-prose</code>, <code>docs-site</code>, <code>docs-check-script</code>, <code>generated-fresh</code>, <code>content-pages</code>, <code>tutorial-count</code>, <code>tutorial-name</code>, <code>index-router</code>, <code>no-orphan-getting-started</code>. Unknown names warn on stderr and are ignored — a typo never fails the run.</td></tr></tbody></table><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;engine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">skip = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs-site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs-check-script&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The tutorial rules pin the golden path: <code>tutorial-count</code> requires <strong>exactly one</strong> markdown file in <code>docs/tutorials/</code> for <code>engine</code> (at most one for <code>library</code>), and <code>tutorial-name</code> requires that tutorial to be <code>getting-started.md</code> — engine-only; <code>library</code> and <code>content</code> SKIP it. Both SKIP when <code>tutorials/</code> is absent.</p><p>Exempted rules still run — the report keeps their evidence, only the status downgrades to <code>SKIP</code>, which never fails the check.</p><h2 id="freshness-—-what-cypera-check-verifies" tabindex="-1">Freshness — what <code>cypera check</code> verifies <a class="header-anchor" href="#freshness-—-what-cypera-check-verifies" aria-label="Permalink to &quot;Freshness — what `cypera check` verifies&quot;">​</a></h2><p><code>cypera check --repo &lt;path&gt;</code> regenerates every declared output in-memory and diffs against the checked-in file — crate-map page, splices, crate-api page, cli page (real <code>--help</code> walk), config page. No writes. A repo without <code>cypera.toml</code> reports the rule as <code>SKIP</code>.</p>',29)])])}const u=t(c,[["render",s]]);export{g as __pageData,u as default};
